#!/usr/bin/env python\n\"\"\"\nBuild standalone executable using PyInstaller\nUsage: python build_exe.py\n\"\"\"\n\nimport os\nimport subprocess\nimport sys\nimport shutil\n\ndef build_dashboard_exe():\n    \"\"\"Build Flask dashboard as standalone exe\"\"\"\n    print(\"🔨 Building Trading Bot Dashboard EXE...\\n\")\n    \n    # PyInstaller command\n    cmd = [\n        sys.executable,\n        \"-m\",\n        \"PyInstaller\",\n        \"--onefile\",\n        \"--windowed\",\n        \"--icon=icon.ico\" if os.path.exists(\"icon.ico\") else \"\",\n        \"--add-data\", \"templates:templates\",\n        \"--add-data\", \".env.example:.env.example\",\n        \"--hidden-import=flask\",\n        \"--hidden-import=flask_cors\",\n        \"--hidden-import=ccxt\",\n        \"--hidden-import=pandas\",\n        \"--hidden-import=numpy\",\n        \"--name\", \"CryptoTradingBot\",\n        \"--distpath\", \"dist\",\n        \"--buildpath\", \"build\",\n        \"--specpath\", \".\",\n        \"dashboard.py\"\n    ]\n    \n    # Remove empty strings\n    cmd = [x for x in cmd if x]\n    \n    try:\n        result = subprocess.run(cmd, check=True)\n        print(\"\\n✅ EXE built successfully!\")\n        print(f\"📦 Location: dist/CryptoTradingBot.exe\")\n        return True\n    except subprocess.CalledProcessError as e:\n        print(f\"\\n❌ Build failed: {e}\")\n        return False\n    except FileNotFoundError:\n        print(\"\\n❌ PyInstaller not found. Install with: pip install pyinstaller\")\n        return False\n\ndef build_cli_exe():\n    \"\"\"Build CLI bot as standalone exe\"\"\"\n    print(\"\\n🔨 Building Trading Bot CLI EXE...\\n\")\n    \n    cmd = [\n        sys.executable,\n        \"-m\",\n        \"PyInstaller\",\n        \"--onefile\",\n        \"--console\",\n        \"--add-data\", \".env.example:.env.example\",\n        \"--hidden-import=ccxt\",\n        \"--hidden-import=pandas\",\n        \"--hidden-import=numpy\",\n        \"--name\", \"CryptoTradingBotCLI\",\n        \"--distpath\", \"dist\",\n        \"bot.py\"\n    ]\n    \n    cmd = [x for x in cmd if x]\n    \n    try:\n        result = subprocess.run(cmd, check=True)\n        print(\"\\n✅ CLI EXE built successfully!\")\n        print(f\"📦 Location: dist/CryptoTradingBotCLI.exe\")\n        return True\n    except subprocess.CalledProcessError as e:\n        print(f\"\\n❌ Build failed: {e}\")\n        return False\n\ndef main():\n    print(\"\"\"\\n\n╔════════════════════════════════════════════════╗\n║   🤖 Crypto Trading Bot - EXE Builder        ║\n║                                                ║\n║   This will create standalone executables    ║\n║   (No Python installation needed!)            ║\n╚════════════════════════════════════════════════╝\n\"\"\")\n    \n    # Check PyInstaller\n    try:\n        import PyInstaller\n    except ImportError:\n        print(\"⚠️  PyInstaller not found.\")\n        print(\"   Install with: pip install pyinstaller\")\n        sys.exit(1)\n    \n    # Clean old builds\n    if os.path.exists(\"build\"):\n        shutil.rmtree(\"build\")\n    if os.path.exists(\"dist\"):\n        shutil.rmtree(\"dist\")\n    \n    # Build executables\n    success = True\n    \n    print(\"\\n[1/2] Building Dashboard (Web Interface)...\")\n    if not build_dashboard_exe():\n        success = False\n    \n    print(\"\\n[2/2] Building CLI (Command Line)...\")\n    if not build_cli_exe():\n        success = False\n    \n    if success:\n        print(\"\\n\" + \"=\"*50)\n        print(\"✅ ALL BUILDS COMPLETED SUCCESSFULLY!\")\n        print(\"=\"*50)\n        print(\"\\n📦 Executables in: dist/\")\n        print(\"\\n🚀 How to use:\")\n        print(\"   1. Open dist/CryptoTradingBot.exe (Dashboard)\")\n        print(\"      OR\")\n        print(\"   2. Run dist/CryptoTradingBotCLI.exe (Command Line)\")\n        print(\"\\n📝 Setup .env file (copy .env.example to .env)\")\n        print(\"\\n✨ No Python installation needed!\\n\")\n    else:\n        print(\"\\n❌ Some builds failed.\")\n        sys.exit(1)\n\nif __name__ == \"__main__\":\n    main()\n"